H.background();
const g = 9.8, h0 = Math.max(1, P.h0);
const tFall = Math.sqrt(2 * h0 / g);
const w = H.W, hh = H.H;
const groundY = hh - 70;
const topY = 80;
const Yof = (yy) => groundY - (yy / h0) * (groundY - topY);
H.line(60, groundY, w - 60, groundY, { color: H.colors.axis, width: 2 });
H.text("ground", w - 110, groundY + 20, { color: H.colors.sub, size: 12 });
const tt = (t % (tFall + 0.6));
let y = h0 - 0.5 * g * tt * tt;
let vel = g * tt;
if (y < 0) { y = 0; vel = g * tFall; }
const ballX = w * 0.5, ballY = Yof(y);
H.line(ballX - 26, topY, ballX + 26, topY, { color: H.colors.grid, width: 2 });
H.circle(ballX, ballY, 12, { fill: H.colors.warn });
H.arrow(ballX, ballY + 14, ballX, ballY + 14 + Math.min(70, vel * 5), { color: H.colors.good, width: 2.5 });
H.text("Free fall:  y = h0 - (1/2) g t^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("g = 9.8 m/s^2   h0 = " + h0.toFixed(1) + " m   t = " + tt.toFixed(2) + " s", 24, 52, { color: H.colors.sub, size: 13 });
H.text("height y = " + y.toFixed(2) + " m   speed v = " + vel.toFixed(2) + " m/s", 24, 74, { color: H.colors.accent, size: 13 });
H.legend([{ label: "g (gravity)", color: H.colors.good }], w - 150, 28);
